Here is a C++ function that converts markdown formatted text to HTML format, using standard library `std::strings`:

```c++
#include <string>
#include <sstream>
#include <ctime>
#include <map>

std::string markdown_to_html(const std::string& markdown) {
  // Create a map of markdown syntax to HTML equivalents
  static const std::map<std::string, std::string> markdown_syntex = {
    {"# ", "<h1>"},  // Heading level 1
    {"## ", "<h2>"},
    {"### ", "<h3>"},
    {"#### ", "<h4>"},
    {"##### ", "<h5>"},
    {"###### ", "<h6>"},
    {"---", "<hr>"}, // Horizontal rule
    {"`", "<code>"}, // Inline code
    {"**", "<strong>"}, // Bold
    {"*", "<em>"}  // Italic
  };

  std::stringstream html;
  for (auto& pair : markdown_syntex) {  // Loop through the map
    std::string markdown_syntax = pair.first;
    std::string html_equivalent = pair.second;
    size_t pos = 0;  // Position in the input string

    while ((pos = markdown.find(markdown_syntax, pos)) != std::string::npos) {
      // Replace markdown syntax with HTML equivalent
      html << markdown.substr(pos, markdown_syntax.length()) << html_equivalent;
      pos += markdown_syntax.length();  // Advance position to next character
    }
  }

  // Handle other markdown features not covered by the map

  // Replace single newlines with HTML paragraph tags
  html << markdown.replace('\n', "</p><p>");

  // Convert inline code to HTML <code> tags
  html << markdown.replace("`", "<code>");

  // Convert links to HTML <a> tags
  html << markdown.replace("[", "<a href=\"").replace("]", "\">");

  // Convert lists to HTML <ul> or <ol> tags
  std::string markdown_list;
  while ((pos = markdown.find(" *", pos)) != std::string::npos) {
    markdown_list += markdown.substr(pos, 3) + "<li>";
    pos += 3;
  }
  html << markdown_list.substr(0, markdown_list.length() - 4);

  // Replace escaped characters (e.g., \n) with their HTML equivalents
  html << markdown.replace("\\n", "<br>");

  return html.str();  // Return the final HTML string
}
```

This function uses a map to convert commonly used markdown syntax to their corresponding HTML equivalents. It iterates through the input markdown string and replaces markdown syntax with HTML tags, handling features like headings, horizontal rules, inline code, bold, italics, links, lists, and escaped characters. The function is designed to be flexible and can handle a variety of markdown syntax elements in a single string.

