A C++ program to count the number of occurrences of a specific word in a text file can be developed as follows:

1. Include necessary headers:
```c++
#include <fstream> // for file input/output
#include <string>  // for working with strings
#include <iostream> // for output
```

2. Define a function to count word occurrences:

```c++
// Function to count the number of occurrences of a specific word in a text file
int countWordOccurences(std::string word, std::string fileName) {
    int count = 0;

    std::ifstream fileStream(fileName); // open file stream

    if (fileStream.is_open()) {
        std::string line;

        while ( std::getline(fileStream, line) ) {
            // Check if current line contains the word
            size_t pos = line.find(word);

            while (pos != std::string::npos) {
                count++;  // increment count if word found

                // Advance to next occurrence of word in the line
                pos = line.find(word, pos + word.length());
            }
        }

        fileStream.close(); // close file stream
    }
    else {
        std::cout << "Error opening file: " << fileName << std::endl;
    }

    return count;
}
```

3. Use the function to count word occurrences in a text file:

```c++
int main() {
    std::string word, fileName; // word to search and file name

    std::cout << "Enter the word you want to count occurrences of: ";
    std::cin >> word; // get word to search for

    std::cout << "Enter the file name: ";
    std::cin >> fileName; // get file name

    int count = countWordOccurences(word, fileName);

    std::cout << "The number of occurrences of '" << word << "' in '" << fileName << "' is: " << count << std::endl;

    return 0;
}
